(()=>{const root=document.documentElement;root.classList.add('js');const blocks=document.querySelectorAll('[data-reveal]');const show=(el)=>el.classList.add('is-shown');if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const io=new IntersectionObserver((entries)=>{entries.forEach((entry)=>{if(entry.isIntersecting){show(entry.target);io.unobserve(entry.target);}});},{threshold:0.18,rootMargin:'0px 0px -60px 0px'});blocks.forEach((el)=>io.observe(el));}else{blocks.forEach(show);}
document.addEventListener('focusin',(e)=>{const b=e.target.closest('[data-reveal]');if(b)show(b);});document.querySelectorAll('[data-scroll]').forEach((a)=>a.addEventListener('click',(e)=>{const target=document.querySelector(a.getAttribute('href'));if(!target)return;e.preventDefault();target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}));const tabs=[...document.querySelectorAll('[data-facility]')];const photos=[...document.querySelectorAll('.facility-photo')];const select=(i)=>{tabs.forEach((t,n)=>t.setAttribute('aria-selected',String(n===i)));photos.forEach((p,n)=>p.classList.toggle('is-active',n===i));};tabs.forEach((t,i)=>{t.addEventListener('click',()=>select(i));t.addEventListener('focus',()=>select(i));t.addEventListener('mouseenter',()=>{if(matchMedia('(hover: hover)').matches)select(i);});});const status=document.getElementById('aboutStatus');let timer;document.querySelector('[data-route="news"]').addEventListener('click',()=>{if(parent===window)location.href='../news/2026-10-22-news-v01.html';else parent.postMessage({namespace:'ctuav-demo',type:'route',route:'news'},'*');});document.querySelector('[data-contact]').addEventListener('click',()=>{if(parent!==window){parent.postMessage({namespace:'ctuav-demo',type:'route',route:'contact'},'*');return;}
status.textContent='Contact CT UAV · Page planned';status.hidden=false;clearTimeout(timer);timer=setTimeout(()=>{status.hidden=true;},3600);});})();addEventListener('message',event=>{if(event.source!==parent||event.data?.namespace!=='ctuav-demo'||event.data.type!=='palette')return;const theme=event.data.theme;document.documentElement.dataset.theme=theme;document.body.dataset.theme=theme;document.querySelectorAll('.palette-button').forEach(button=>{button.classList.toggle('selected',button.dataset.palette===theme);button.setAttribute('aria-pressed',String(button.dataset.palette===theme));});});addEventListener('message',event=>{if(event.source===parent&&event.data?.namespace==='ctuav-demo'&&event.data.type==='view-active'&&event.data.active)scrollTo({top:0,behavior:'instant'});});"use strict";(()=>{document.querySelectorAll('[data-footer-route]').forEach((button)=>button.addEventListener('click',()=>{const route=button.dataset.footerRoute;if(window.ctuavDemo)window.ctuavDemo.navigate(route);else if(parent!==window)parent.postMessage({namespace:'ctuav-demo',type:'route',route},'*');}));})();